const body = $input.first().json.body;
// Deterministic defaulting only (github_owner/github_repo/current_date). language and
// expertise_level are never looked at, looked up, bounds-checked, or defaulted here --
// both flow straight through the ...cleanBody spread from whatever the payload already
// has, unchanged, across every workflow. Intention-Graph fields (active_node_id,
// intention_nodes) pass through untouched via the ...cleanBody spread too -- interpreting/
// normalizing them is Intent Manager's job, not this node's.
// parent_override_id/pending_processes/awaiting_batch_confirmation/pending_batch_items/
// process_stack/awaiting_stack_resume/paused_node_ids are dropped here -- confirmed dead
// (2026-08-13 audit): nothing in v14 ever populates a real disambiguation menu or
// batch-confirm gate, process_stack only ever duplicated data already on intention_nodes,
// the stack-resume confirmation flow has no live trigger, and paused_node_ids was a pure
// restatement of intention_nodes[id].status === 'paused' with zero external readers.
// process_id/process_definition/form_state (root-level) are dropped too -- confirmed dead
// the same audit: every consumer now reads intention_nodes[active_node_id] directly
// instead of a root-level working copy that had to be kept in sync every turn.
// active_node_override is dropped too -- clicking a node in the Intention Graph now
// switches the active node directly in Django (active_node_switch, consumers/chat.py),
// with no n8n round-trip at all; this workflow never receives that field anymore.
// process_queue is dropped too -- confirmed dead the same audit: Agent: Form computed it
// but nothing ever read it back (Django's _resolve_and_persist_state never persisted it,
// SAP Inquiry Execution never looped over it), so multiple separate instances of a process
// silently only ever created the first one. Requesting several instances at once is
// already handled correctly by Agent: Find's own new_intent_status: 'batch' path.
const {
  parent_override_id: _deadParentOverrideId,
  pending_processes: _deadPendingProcesses,
  awaiting_batch_confirmation: _deadAwaitingBatchConfirmation,
  pending_batch_items: _deadPendingBatchItems,
  process_stack: _deadProcessStack,
  awaiting_stack_resume: _deadAwaitingStackResume,
  paused_node_ids: _deadPausedNodeIds,
  process_id: _deadProcessId,
  process_definition: _deadProcessDefinition,
  form_state: _deadFormState,
  active_node_override: _deadActiveNodeOverride,
  process_queue: _deadProcessQueue,
  ...cleanBody
} = body;

return [{ json: {
  ...cleanBody,
  github_owner: 'blasvicco',
  github_repo: 'da-sapot-processes',
  current_date: new Date().toISOString().split('T')[0],
  intention_nodes: body.intention_nodes || {},
} }];
